# -*- coding: utf-8 -*-
import html,json,pathlib
from extract_pdf_line_geometry import ROOT,V4,OUT
from build_physical_graphs import read,write,sha,rel

CSS='''*{box-sizing:border-box}body{font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif;color:#203044;background:#f4f6f9;margin:0}main{max-width:1280px;margin:30px auto;padding:0 24px}h1{font-size:30px;line-height:1.3}h2{font-size:21px}section{background:white;padding:22px 26px;border:1px solid #dce3eb;border-radius:12px;margin:20px 0}a{color:#126394}small,.muted{color:#65748a}details{margin:9px 0 9px 15px;padding-left:14px;border-left:2px solid #d7e2eb}summary{cursor:pointer;padding:5px}article{background:#f1f6fa;border-radius:8px;padding:16px 20px;margin:12px 0;scroll-margin:20px}article:target{outline:3px solid #439ba0}pre{font:16px/1.9 system-ui;white-space:pre-wrap;overflow-wrap:anywhere}button,input{font:inherit;border:1px solid #b7c9d7;border-radius:6px;background:#fff;padding:8px 12px;margin:4px}button{cursor:pointer}input{min-width:300px}.stats{display:flex;gap:35px;flex-wrap:wrap}.stat b{display:block;font-size:28px;color:#13616c}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #e1e7ed;padding:9px}.pill{display:inline-block;border-radius:20px;background:#e0eef1;color:#235a63;font-size:13px;padding:3px 9px}.links{display:flex;gap:18px;flex-wrap:wrap}iframe{width:100%;height:75vh;border:1px solid #d3dae1}.compare{display:grid;grid-template-columns:1fr 1.5fr;gap:20px}@media(max-width:850px){.compare{display:block}input{min-width:180px}}'''

def page(title,body,script=''):
    return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+CSS+'</style><main>'+body+'</main><script>'+script+'</script></html>'

VIEWER=r'''
const el=id=>document.getElementById(id);let nodes={},root,cache={},elements={};const labels={book:'书',chapter:'章',section:'节',subsection:'小节'};const bid=new URLSearchParams(location.search).get('book');
function count(id){return cache[id]??(cache[id]=nodes[id].type==='paragraph'?1:nodes[id].children.reduce((a,c)=>a+count(c),0))}
function paragraph(n){let a=document.createElement('article');a.id=n.id;let meta=document.createElement('small');let text=document.createElement('pre');text.textContent=n.text;let status=n.pdf_layout_status==='repaired_from_pdf_pixels'?'本轮按原页修复':n.pdf_layout_status==='line_alignment_pending'?'文字与原页坐标对齐待复核':'已检查原页版面，沿用当前边界';meta.textContent='段落 · PDF '+(n.pdf_pages.join('、')||n.source_spans.map(x=>x.page_pdf).join('、'))+' · '+status+(n.ownership_status==='unresolved'?' · 章节归属待复核':'');let link=document.createElement('a');link.href='原页对照.html?book='+bid+'&node='+encodeURIComponent(n.id);link.textContent='查看段落与原 PDF 对照 →';a.append(meta,text,link);if(n.quality_flags.length){let note=document.createElement('small');note.textContent='　原有质量标记保留';a.append(note)}return a}
function item(id){let n=nodes[id];if(n.type==='paragraph')return paragraph(n);let d=document.createElement('details'),s=document.createElement('summary'),box=document.createElement('div');s.textContent=(labels[n.type]||n.type)+' · '+n.label+'（'+count(id)+' 段）';d.append(s,box);elements[id]=d;d.ontoggle=()=>{if(d.open&&!d.dataset.loaded){d.dataset.loaded='1';if(n.type==='book'){for(let c of n.children.filter(c=>nodes[c].type!=='paragraph'))box.append(item(c));let direct=n.children.filter(c=>nodes[c].type==='paragraph');if(direct.length){let v=document.createElement('details'),t=document.createElement('summary');t.textContent='书前内容及章归属待核内容（'+direct.length+' 段）';v.append(t);v.ontoggle=()=>{if(v.open&&!v.dataset.loaded){v.dataset.loaded='1';direct.forEach(c=>v.append(item(c)))}};box.append(v);elements.direct=v}}else n.children.forEach(c=>box.append(item(c)))}};return d}
function reset(){elements={};el('tree').replaceChildren(item(root));elements[root].open=true;elements[root].dispatchEvent(new Event('toggle'))}
function expand(n){for(let id of n.path_ids){if(elements[id]){elements[id].open=true;elements[id].dispatchEvent(new Event('toggle'))}}if(n.type==='paragraph'&&n.parent_id===root&&elements.direct){elements.direct.open=true;elements.direct.dispatchEvent(new Event('toggle'))}let e=document.getElementById(n.id);if(e){e.scrollIntoView();e.style.outline='2px solid #398a97'}}
el('reset').onclick=reset;el('search').onclick=()=>{let q=el('query').value.trim();if(!q)return;let hits=Object.values(nodes).filter(n=>(n.label||n.text||'').includes(q));hits.slice(0,20).forEach(expand);el('status').textContent='匹配 '+hits.length+' 项，展开前 '+Math.min(hits.length,20)+' 项'};
(async()=>{try{let g=await(await fetch(bid+'/hierarchy_graph.json')).json();nodes=Object.fromEntries(g.nodes.map(n=>[n.id,n]));root=g.root_id;el('title').textContent=g.book_title;el('status').textContent=count(root).toLocaleString()+' 段全部纳入，保留实际章节深度。';reset();let node=new URLSearchParams(location.search).get('node');if(nodes[node])expand(nodes[node])}catch(e){el('title').textContent='读取失败：'+e.message}})();
'''

COMPARE=r'''
const el=id=>document.getElementById(id);let q=new URLSearchParams(location.search),bid=q.get('book'),nid=q.get('node');
(async()=>{try{let g=await(await fetch(bid+'/hierarchy_graph.json')).json(),n=g.nodes.find(x=>x.id===nid);if(!n)throw Error('段落不存在');el('back').href='层级查看.html?book='+bid+'&node='+encodeURIComponent(nid);el('title').textContent=g.book_title;el('text').textContent=n.text;let lookup=Object.fromEntries(g.nodes.map(n=>[n.id,n]));el('path').textContent=n.path_ids.slice(0,-1).map(x=>lookup[x].label).join(' → ');el('note').textContent='段落节点 '+nid+'。原始文本字符范围、PDF 行框和页码均保留在数据文件中。';let seen=new Set;for(let e of n.pdf_evidence){let key=e.pdf_path+'#'+e.local_pdf_page;if(seen.has(key)||!e.local_pdf_page)continue;seen.add(key);let url='../../'+e.pdf_path.split('/').map(encodeURIComponent).join('/')+'#page='+e.local_pdf_page;let a=document.createElement('a');a.href=url;a.target='_blank';a.textContent='原 PDF 第 '+e.pdf_page+' 页（文件内第 '+e.local_pdf_page+' 页）';a.onclick=event=>{event.preventDefault();el('pdf').src='http://127.0.0.1:8766/page?book='+encodeURIComponent(bid)+'&page='+e.pdf_page;el('imageLink').href=el('pdf').src;el('external').href=url};el('pages').append(a);if(seen.size===1){el('pdf').src='http://127.0.0.1:8766/page?book='+encodeURIComponent(bid)+'&page='+e.pdf_page;el('imageLink').href=el('pdf').src;el('external').href=url}}if(!seen.size){el('note').textContent+=' 该段的行坐标对齐尚未确定，保留源记录，未标记为已核实。';el('pdf').remove();el('external').remove()}el('raw').href=bid+'/text_graph.json'}catch(e){el('title').textContent=e.message}})();
'''

def main():
    m=read(OUT/'manifest.json');v=read(OUT/'验收结果.json');assert v['status']=='passed'
    s=m['summary'];geo=read(OUT/'PDF几何覆盖.json');relocated=sum(b['cross_page_lines_relocated'] for b in geo['books'])
    rows=''.join('<tr><td><a href="层级查看.html?book='+b['book_id']+'">'+html.escape(b['book_title'])+'</a></td><td>'+format(b['paragraphs'],',')+'</td><td>'+str(b['added_internal_boundaries'])+'</td><td>'+str(b['merged_record_boundaries'])+'</td></tr>' for b in m['books'])
    stats='<div class="stats">'+''.join('<div class="stat"><b>'+format(n,',')+'</b>'+t+'</div>' for n,t in [(24,'本教材'),(s['paragraphs'],'段落节点'),(s['added_internal_boundaries'],'处补充分段'),(s['merged_record_boundaries'],'处续段合并'),(relocated,'行跨页位置修正')])+'</div>'
    body='<span class="pill">PDF 原页版面修复 · v5</span><h1>书名 → 章 → 节 → 小节 → 段落</h1><p>这次以原 PDF 的段首、行间距和跨页位置为依据修复段落边界。所有正文继续保留在完整层级中。</p><section>'+stats+'</section><section><h2>这版修复了什么</h2><p>逐页渲染并处理 13,187 页原 PDF，修正 OCR 已跨页合并却仍指向第一页的文字位置；将证据明确的粘连自然段拆开，将错误分开的续段合并。图表、公式和程序保留原有类型，原先的证据修正全部保留。</p><p>自动检查和所列原页抽查已完成。复杂排版、文字对齐和章节归属仍有待复核项；这版不能宣称每个段落都已逐一人工确认。质量标记不会把正文从全量图中排除。</p><div class="links"><a href="验收结果.json">完整性验收</a><a href="PDF几何覆盖.json">原 PDF 覆盖记录</a><a href="原页抽查记录.json">原页抽查记录</a><a href="全量正文段落.jsonl">全量段落数据</a><a href="层级数据清单.json">24 本图数据清单</a></div></section><section><h2>直接看一个修复例子</h2><p>C++ Primer Plus 的 PDF 第 46 页，“不要混淆函数原型和函数定义”在原页另起一段。新版已按这个段首拆开。</p><a href="层级查看.html?book=book_ab313ee3c3dd&node=pdfpara%3Abook_ab313ee3c3dd%3A600%3A54%3A184">打开该段及章节层级 →</a></section><section><h2>选择教材</h2><table><thead><tr><th>教材</th><th>段落节点</th><th>补充分段</th><th>续段合并</th></tr></thead><tbody>'+rows+'</tbody></table></section>'
    (OUT/'修复结果.html').write_text(page('PDF 自然段修复结果',body),encoding='utf8')
    (OUT/'层级结构入口.html').write_text(page('PDF 自然段文本图',body),encoding='utf8')
    (OUT/'层级查看.html').write_text(page('章节树与 PDF 段落','<a href="修复结果.html">← 24 本修复结果</a><h1 id="title">读取中…</h1><p>原 PDF 段落边界自动修复版。点击章、节、小节展开；每段可打开原 PDF 对照。全部正文保留，尚未逐段人工确认。</p><section><input id="query" placeholder="查找章节或正文"><button id="search">查找并展开</button><button id="reset">收起全部</button><p id="status"></p></section><section id="tree"></section>',VIEWER),encoding='utf8')
    (OUT/'原页对照.html').write_text(page('段落与原 PDF 对照','<a id="back">← 返回章节树</a><h1 id="title">读取中…</h1><p id="path"></p><div class="compare"><section><h2>文本图中的段落</h2><pre id="text"></pre><p id="note" class="muted"></p><a id="raw">查看原始图数据</a></section><section><h2>原 PDF 页面</h2><p id="pages" class="links"></p><p><a id="external" target="_blank">单独打开 PDF（预览未显示时使用）</a></p><a id="imageLink" target="_blank"><img id="pdf" alt="原 PDF 页面图像，点击放大" style="width:100%;height:auto;border:1px solid #d3dae1"></a></section></div>',COMPARE),encoding='utf8')
    pointer=read(ROOT/'研究方案_20261002/24本文本图_当前版本.json')
    if not (OUT/'previous_current_pointer.json').exists():write(OUT/'previous_current_pointer.json',pointer)
    pointer.update(version='v5',previous_version='v4',data_directory=rel(OUT),manifest_path=rel(OUT/'manifest.json'),manifest_sha256=sha(OUT/'manifest.json'),report_path=rel(OUT/'修复结果.html'),repair_report_path=rel(OUT/'修复结果.html'),hierarchy_manifest_path=rel(OUT/'层级数据清单.json'),hierarchy_graph_filename='hierarchy_graph.json',full_paragraph_corpus_path=rel(OUT/'全量正文段落.jsonl'),full_corpus_natural_paragraph_verified=False,human_verified=False,latest_corpus_audit={'conclusion_path':rel(OUT/'验收结果.json'),'acceptance':'source_and_hierarchy_passed_full_semantic_verification_pending','paragraphs':s['paragraphs'],'original_pdf_pages_processed':geo['original_pdf_pages_rendered'],'visual_sample_record_path':rel(OUT/'原页抽查记录.json')})
    # Remove stale v4 paths only when a corresponding v5 artifact is available.
    for k,val in list(pointer.items()):
        if isinstance(val,str) and '24本文本图_物理段落v4_20261003/' in val:
            candidate=val.replace('24本文本图_物理段落v4_20261003/','24本文本图_PDF自然段修复v5_20261003/')
            if (ROOT/candidate).exists():pointer[k]=candidate
            else:pointer.pop(k)
    write(ROOT/'研究方案_20261002/24本文本图_当前版本.json',pointer)
    print(json.dumps({'published':rel(OUT/'修复结果.html'),'summary':s},ensure_ascii=False))

if __name__=='__main__':main()
